    private static let safetyScenarios = Exercise(
        title: "Sicurezza in casa e per strada",
        instructions: "Legga la situazione e scriva che cosa farebbe.",
        section: .functionalSkills,
        type: .openEnded,
        trackedType: nil,
        difficulty: .medium,
        groupKey: "safetyScenarios",
        isHeldForReview: true,
        items: [
            ExerciseItem(id: UUID(), prompt: "Entra in cucina e sente un forte odore di gas. Che cosa fa?", options: [], correctAnswer: "Non accendo luci, fiammiferi o accendini e non uso il telefono in casa. Apro le finestre, chiudo il rubinetto del gas e esco. Poi chiamo il 115 (Vigili del Fuoco) da fuori.", explanation: "Una scintilla può far esplodere il gas. Ventilare, chiudere il gas e allontanarsi sono le prime mosse; i Vigili del Fuoco gestiscono la fuga."),
            ExerciseItem(id: UUID(), prompt: "Di sera vede fumo uscire da una stanza del Suo appartamento. Che cosa fa?", options: [], correctAnswer: "Esco subito, chiudo la porta dietro di me senza rientrare a prendere oggetti e non uso l'ascensore. Dal pianerottolo o dalla strada chiamo il 115 (oppure il 112) e dico l'indirizzo.", explanation: "Il fumo è pericoloso quanto le fiamme. Chiudere la porta rallenta l'incendio e l'ascensore può bloccarsi: contano la propria sicurezza e una chiamata rapida."),
            ExerciseItem(id: UUID(), prompt: "Suona il citofono un uomo che dice di essere un tecnico del gas e vuole entrare per un controllo urgente. Non l'aspettava. Che cosa fa?", options: [], correctAnswer: "Non apro la porta. Chiedo il suo nome e quello dell'azienda, poi telefono all'azienda al numero scritto sulla bolletta per verificare. Se insiste o mi sento minacciato, chiamo il 112.", explanation: "I veri tecnici sono annunciati prima. Verificare al numero ufficiale della bolletta, e non a quello dato dallo sconosciuto, protegge da chi vuole entrare per rubare."),
            ExerciseItem(id: UUID(), prompt: "Per strada vede una persona a terra che non risponde quando la chiama. Che cosa fa?", options: [], correctAnswer: "Mi avvicino con attenzione, chiamo il 118, dico dove mi trovo e come sta la persona, e seguo le indicazioni dell'operatore. Resto sul posto finché arrivano i soccorsi.", explanation: "L'operatore del 118 guida chi chiama passo per passo. Dare l'indirizzo preciso fa arrivare l'ambulanza più in fretta."),
            ExerciseItem(id: UUID(), prompt: "Riceve una telefonata: una voce dice di essere della Sua banca e chiede i codici della Sua carta per bloccare un pagamento sospetto. Che cosa fa?", options: [], correctAnswer: "Non do nessun codice e riattacco. Poi chiamo io la banca al numero scritto sulla carta o sul sito ufficiale. Se ho già dato dei dati, avviso subito la banca e poi il 112.", explanation: "Una banca non chiede mai PIN o codici per telefono. Richiamare al numero ufficiale permette di capire se il problema è vero."),
            ExerciseItem(id: UUID(), prompt: "Un uomo Le strappa la borsa mentre cammina e scappa. Che cosa fa?", options: [], correctAnswer: "Non lo inseguo. Mi metto in un luogo sicuro, chiamo il 112 o il 113 e descrivo la persona e la direzione in cui è andata. Poi faccio bloccare le carte e presento denuncia.", explanation: "Inseguire un ladro può essere pericoloso e non serve. Descrivere bene la scena aiuta la Polizia, e bloccare le carte evita altri danni."),
            ExerciseItem(id: UUID(), prompt: "Di notte sente rumori alla porta, come se qualcuno cercasse di forzarla. Che cosa fa?", options: [], correctAnswer: "Non vado a vedere e non affronto nessuno. Mi chiudo in una stanza con il telefono, chiamo il 112 o il 113 e dico il mio indirizzo. Resto in linea finché mi dicono di fare diversamente.", explanation: "Il rischio maggiore è l'incontro diretto. Restare al sicuro e far arrivare le forze dell'ordine protegge più di qualsiasi reazione."),
            ExerciseItem(id: UUID(), prompt: "In bagno il pavimento è bagnato e scivoloso dopo la doccia. Che cosa fa per non cadere?", options: [], correctAnswer: "Asciugo subito il pavimento, uso un tappetino antiscivolo, accendo la luce e mi tengo alla maniglia o al sostegno quando esco dalla doccia.", explanation: "Molte cadute in casa avvengono in bagno. Un pavimento asciutto e un appoggio stabile riducono molto il rischio."),
            ExerciseItem(id: UUID(), prompt: "Deve attraversare una strada trafficata e a venti metri c'è un passaggio pedonale con semaforo. Che cosa fa?", options: [], correctAnswer: "Vado al passaggio pedonale, aspetto il verde pedonale, guardo a destra e a sinistra e attraverso con calma, senza usare il telefono.", explanation: "Le strisce con semaforo sono il punto in cui gli automobilisti sono obbligati a fermarsi. Guardare comunque evita il pericolo di chi non rispetta il rosso."),
            ExerciseItem(id: UUID(), prompt: "Una presa elettrica in cucina fa scintille e c'è odore di bruciato. Che cosa fa?", options: [], correctAnswer: "Non la tocco. Se posso farlo senza rischio, abbasso l'interruttore generale del quadro elettrico e chiamo un elettricista. Se vedo fiamme, esco e chiamo il 115.", explanation: "Togliere la corrente toglie la causa del problema. Toccare una presa che scintilla o usare acqua può causare una scossa."),
            ExerciseItem(id: UUID(), prompt: "L'olio in una padella sul fuoco prende fiamma. Che cosa fa?", options: [], correctAnswer: "Spengo il fuoco e copro la padella con un coperchio, senza mai buttare acqua. Se le fiamme non si spengono subito, esco e chiamo il 115.", explanation: "L'acqua sull'olio bollente schizza e allarga le fiamme. Il coperchio toglie l'ossigeno e spegne il fuoco."),
            ExerciseItem(id: UUID(), prompt: "Si accorge di aver perso il portafoglio con le carte e i documenti. Che cosa fa?", options: [], correctAnswer: "Controllo dove sono stato, poi chiamo subito la banca per bloccare le carte. Presento denuncia di smarrimento alle forze dell'ordine e avviso il Comune per i documenti.", explanation: "Bloccare le carte subito impedisce pagamenti non Suoi. La denuncia serve per chiedere i documenti nuovi."),
            ExerciseItem(id: UUID(), prompt: "Si è perso in una zona della città che non conosce e il telefono è quasi scarico. Che cosa fa?", options: [], correctAnswer: "Mi fermo in un luogo illuminato e sicuro, per esempio un negozio o un bar, e chiedo aiuto. Chiamo un familiare e dico dove sono; se mi sento in pericolo chiamo il 112.", explanation: "Camminare ancora a caso può peggiorare le cose. Un negozio è un posto sicuro dove trovare indicazioni e magari una presa per ricaricare."),
            ExerciseItem(id: UUID(), prompt: "In un edificio pubblico suona l'allarme antincendio. Che cosa fa?", options: [], correctAnswer: "Mantengo la calma, seguo i cartelli verdi delle uscite di sicurezza e scendo dalle scale, non con l'ascensore. Una volta fuori, raggiungo il punto di raccolta e non rientro.", explanation: "Le uscite di sicurezza sono pensate per svuotare l'edificio in modo ordinato. L'ascensore può fermarsi con il fumo o senza corrente."),
            ExerciseItem(id: UUID(), prompt: "Mentre è in casa sente la terra tremare: è un terremoto. Che cosa fa?", options: [], correctAnswer: "Mi riparo sotto un tavolo robusto o accanto a un muro portante, lontano da finestre e mobili alti. Quando la scossa finisce esco con calma dalle scale, senza ascensore, e vado in uno spazio aperto.", explanation: "Durante la scossa il pericolo sono gli oggetti che cadono. Dopo, uscire all'aperto evita il rischio di crolli e di nuove scosse dentro casa."),
            ExerciseItem(id: UUID(), prompt: "È stata annunciata un'allerta per piogge molto forti e la Sua casa ha un seminterrato. Che cosa fa?", options: [], correctAnswer: "Non scendo in cantina o in garage, non cammino né guido nelle strade allagate e salgo ai piani alti se l'acqua entra. Se sono in difficoltà chiamo il 112.", explanation: "L'acqua sale in fretta nei locali bassi e le strade allagate nascondono buche e correnti."),
            ExerciseItem(id: UUID(), prompt: "La Sua vicina anziana, che vedeva ogni giorno, non risponde al campanello da due giorni. Che cosa fa?", options: [], correctAnswer: "Chiedo agli altri vicini e telefono ai suoi familiari se ho il numero. Se nessuno la trova e ho il timore che stia male, chiamo il 112 e non cerco di entrare da solo.", explanation: "Prima si cercano spiegazioni semplici. Se il timore resta, i soccorsi hanno gli strumenti per entrare in sicurezza."),
            ExerciseItem(id: UUID(), prompt: "Ha mal di testa e nausea, e il vicino sente la stessa cosa: la caldaia in casa fa un rumore strano e ha una fiamma gialla. Che cosa fa?", options: [], correctAnswer: "Apro porte e finestre, spengo la caldaia e esco all'aria aperta con le persone presenti. Chiamo il 118 per i sintomi e il 115 per il controllo della caldaia.", explanation: "Una caldaia che funziona male può produrre monossido di carbonio, un gas senza odore e molto pericoloso. L'aria fresca è la prima cosa da fare."),
            ExerciseItem(id: UUID(), prompt: "Pulendo il bagno ha mescolato candeggina e un altro detersivo e sente un odore pungente che irrita la gola. Che cosa fa?", options: [], correctAnswer: "Esco dalla stanza e apro le finestre per arieggiare, senza respirare i vapori. Se ho difficoltà a respirare o la gola brucia, chiamo il 118. In futuro non mescolo mai prodotti diversi.", explanation: "Alcuni detersivi insieme liberano gas irritanti. Allontanarsi e arieggiare è la prima misura."),
            ExerciseItem(id: UUID(), prompt: "Torna a casa e trova la porta socchiusa con la serratura rotta. Che cosa fa?", options: [], correctAnswer: "Non entro. Mi allontano subito e chiamo il 112 o il 113 da fuori, dicendo il mio indirizzo. Aspetto l'arrivo della Polizia senza toccare nulla.", explanation: "I ladri potrebbero essere ancora dentro. Aspettare fuori protegge Lei e conserva le tracce utili alle indagini."),
            ExerciseItem(id: UUID(), prompt: "Per strada assiste a un incidente stradale con una persona ferita. Che cosa fa?", options: [], correctAnswer: "Mi fermo in un punto sicuro, chiamo il 112 o il 118, dico dove è successo e quante persone sono coinvolte. Non muovo il ferito e segnalo il pericolo agli altri automobilisti.", explanation: "Una chiamata chiara e precisa fa partire i soccorsi giusti. Tenersi lontani dalla corsia evita un secondo incidente."),
            ExerciseItem(id: UUID(), prompt: "Dopo un temporale vede un cavo elettrico caduto a terra in strada. Che cosa fa?", options: [], correctAnswer: "Mi tengo a distanza, non lo tocco e avviso gli altri di non avvicinarsi. Chiamo il 115 (oppure il 112) e comunico il punto preciso.", explanation: "Un cavo a terra può essere ancora sotto tensione anche se sembra spento, e la corrente può passare attraverso l'acqua."),
            ExerciseItem(id: UUID(), prompt: "Riceve un messaggio che dice: «Il Suo pacco è in giacenza, clicchi qui e paghi 1,50 € per la consegna». Non aspetta nessun pacco. Che cosa fa?", options: [], correctAnswer: "Non clicco sul link e non inserisco i dati della carta. Cancello il messaggio e, se ho dubbi, controllo sul sito del corriere digitando io l'indirizzo.", explanation: "È una truffa molto comune: la piccola cifra serve per rubare i dati della carta. I messaggi che mettono fretta sono un campanello d'allarme."),
            ExerciseItem(id: UUID(), prompt: "Mentre è solo in casa avverte un forte dolore al petto e si sente mancare il fiato. Che cosa fa?", options: [], correctAnswer: "Chiamo subito il 118 e dico chiaramente il mio indirizzo e come mi sento. Mi siedo, lascio la porta di casa sbloccata se posso farlo e resto al telefono finché arrivano.", explanation: "Il dolore al petto può essere grave e ogni minuto conta. Non conviene aspettare che passi: l'operatore del 118 sa dire come comportarsi."),
            ExerciseItem(id: UUID(), prompt: "In cucina scopre una perdita d'acqua sotto il lavello e il pavimento si sta allagando. Che cosa fa?", options: [], correctAnswer: "Chiudo il rubinetto d'arresto sotto il lavello o quello generale dell'acqua. Se l'acqua è vicina a prese o elettrodomestici, abbasso prima la corrente. Poi asciugo e chiamo un idraulico.", explanation: "Fermare l'acqua alla fonte limita i danni. Acqua ed elettricità insieme sono pericolose, quindi si toglie la corrente.")
        ]
    )

