        items: [
            ExerciseItem(id: UUID(), prompt: "Il negozio di scarpe apre alle 08:30 e chiude per la pausa alle 12:45. Per quanto tempo resta aperto la mattina?", options: ["4 ore e 15 minuti", "4 ore e 25 minuti", "3 ore e 45 minuti", "4 ore e 45 minuti"], correctAnswer: "4 ore e 15 minuti", explanation: "Da 08:30 a 12:30 passano 4 ore, e da 12:30 a 12:45 altri 15 minuti: in tutto 4 ore e 15 minuti."),
            ExerciseItem(id: UUID(), prompt: "Il treno parte alle 14:50 e il viaggio dura 1 ora e 35 minuti. A che ora arriva?", options: ["16:15", "16:25", "16:35", "16:45"], correctAnswer: "16:25", explanation: "14:50 + 1 ora = 15:50. Poi 15:50 + 35 minuti = 16:25 (10 minuti portano alle 16:00, altri 25 alle 16:25)."),
            ExerciseItem(id: UUID(), prompt: "Al supermercato la spesa costa 18,40 €. Paga con una banconota da 20 €. Quanto deve ricevere di resto?", options: ["1,40 €", "1,60 €", "2,40 €", "2,60 €"], correctAnswer: "1,60 €", explanation: "Il resto è 20,00 € - 18,40 € = 1,60 €."),
            ExerciseItem(id: UUID(), prompt: "Una giacca costa 80 €. Oggi c'è lo sconto del 25%. Quanto si paga?", options: ["55 €", "60 €", "64 €", "75 €"], correctAnswer: "60 €", explanation: "Il 25% di 80 € è 80 : 4 = 20 €. Il prezzo scontato è 80 € - 20 € = 60 €."),
            ExerciseItem(id: UUID(), prompt: "Le mele costano 2,20 € al chilo. Quanto si paga per 3 kg?", options: ["5,60 €", "6,20 €", "6,60 €", "7,60 €"], correctAnswer: "6,60 €", explanation: "3 × 2,20 € = 6,60 € (2,20 € + 2,20 € + 2,20 €)."),
            ExerciseItem(id: UUID(), prompt: "Un autobus passa ogni 20 minuti. Sono passati quelli delle 07:10, delle 07:30 e delle 07:50, e Lei li ha persi. A che ora passa il prossimo?", options: ["08:00", "08:10", "08:20", "08:30"], correctAnswer: "08:10", explanation: "Dopo le 07:50 si aggiungono 20 minuti: 07:50 + 20 minuti = 08:10."),
            ExerciseItem(id: UUID(), prompt: "La farmacia chiude alle 19:30. Ora sono le 17:50. Quanto tempo manca alla chiusura?", options: ["80 minuti", "90 minuti", "100 minuti", "110 minuti"], correctAnswer: "100 minuti", explanation: "Da 17:50 alle 18:00 passano 10 minuti, da 18:00 alle 19:30 altri 90: 10 + 90 = 100 minuti, cioè 1 ora e 40."),
            ExerciseItem(id: UUID(), prompt: "Un biglietto del cinema costa 8,50 €. Quanto pagano due persone in tutto?", options: ["16 €", "17 €", "17,50 €", "18 €"], correctAnswer: "17 €", explanation: "2 × 8,50 € = 17,00 €, perché 8 € + 8 € = 16 € e 0,50 € + 0,50 € = 1 €."),
            ExerciseItem(id: UUID(), prompt: "Al bar prende un caffè da 1,20 € e un cornetto da 1,30 €. Paga con 5 €. Quanto riceve di resto?", options: ["2,30 €", "2,50 €", "2,70 €", "3,50 €"], correctAnswer: "2,50 €", explanation: "La spesa è 1,20 € + 1,30 € = 2,50 €. Il resto è 5,00 € - 2,50 € = 2,50 €."),
            ExerciseItem(id: UUID(), prompt: "Parte da casa alle 09:15 e arriva dal medico alle 11:05. Quanto è durato il viaggio?", options: ["1 ora e 40 minuti", "1 ora e 50 minuti", "2 ore e 10 minuti", "2 ore e 20 minuti"], correctAnswer: "1 ora e 50 minuti", explanation: "Da 09:15 alle 11:15 sarebbero 2 ore, ma si arriva 10 minuti prima: 2 ore - 10 minuti = 1 ora e 50 minuti."),
            ExerciseItem(id: UUID(), prompt: "Quattro amici vanno a cena e il conto è di 46 €. Dividono la cifra in parti uguali. Quanto paga ciascuno?", options: ["10,50 €", "11,25 €", "11,50 €", "12 €"], correctAnswer: "11,50 €", explanation: "46 € : 4 = 11,50 €. Controllo: 11,50 € × 4 = 46 €."),
            ExerciseItem(id: UUID(), prompt: "La bolletta della luce è di 64,80 € e viene pagata in 3 rate uguali. Quanto costa ogni rata?", options: ["20,60 €", "21,60 €", "21,80 €", "22,60 €"], correctAnswer: "21,60 €", explanation: "64,80 € : 3 = 21,60 €. Controllo: 21,60 € × 3 = 64,80 €."),
            ExerciseItem(id: UUID(), prompt: "Un biglietto dell'autobus costa 1,50 €. Lei fa 2 corse al giorno per 5 giorni. Quanto spende in tutto?", options: ["7,50 €", "10 €", "15 €", "30 €"], correctAnswer: "15 €", explanation: "Le corse sono 2 × 5 = 10. La spesa è 10 × 1,50 € = 15 €."),
            ExerciseItem(id: UUID(), prompt: "Ha una visita dal medico alle 10:20 e il tragitto richiede 35 minuti. A che ora deve uscire di casa, al più tardi?", options: ["09:35", "09:45", "09:55", "10:55"], correctAnswer: "09:45", explanation: "10:20 - 35 minuti: 10:20 - 20 minuti = 10:00, poi altri 15 minuti = 09:45."),
            ExerciseItem(id: UUID(), prompt: "Compra 2 litri di latte a 1,35 € al litro e un pane da 1,80 €. Paga con 10 €. Quanto riceve di resto?", options: ["4,50 €", "5,30 €", "5,50 €", "6,50 €"], correctAnswer: "5,50 €", explanation: "Il latte costa 2 × 1,35 € = 2,70 €. In tutto 2,70 € + 1,80 € = 4,50 €. Il resto è 10,00 € - 4,50 € = 5,50 €."),
            ExerciseItem(id: UUID(), prompt: "Un paio di scarpe costa 120 € e ha lo sconto del 30%. Quanto si paga?", options: ["36 €", "84 €", "90 €", "94 €"], correctAnswer: "84 €", explanation: "Il 10% di 120 € è 12 €, quindi il 30% è 36 €. Il prezzo è 120 € - 36 € = 84 €."),
            ExerciseItem(id: UUID(), prompt: "Cammina a 4 km/h per 2 ore e mezza. Quanti chilometri percorre?", options: ["6 km", "8 km", "10 km", "12 km"], correctAnswer: "10 km", explanation: "In 2 ore fa 2 × 4 = 8 km. In mezz'ora ne fa 2. In totale 8 + 2 = 10 km."),
            ExerciseItem(id: UUID(), prompt: "Il film inizia alle 20:40 e dura 2 ore e 10 minuti. A che ora finisce?", options: ["22:10", "22:40", "22:50", "23:10"], correctAnswer: "22:50", explanation: "20:40 + 2 ore = 22:40. Poi 22:40 + 10 minuti = 22:50."),
            ExerciseItem(id: UUID(), prompt: "Le banane costano 1,80 € al chilo. Quanto si paga per 500 g?", options: ["0,18 €", "0,80 €", "0,90 €", "1,80 €"], correctAnswer: "0,90 €", explanation: "500 g sono mezzo chilo, quindi si paga la metà: 1,80 € : 2 = 0,90 €."),
            ExerciseItem(id: UUID(), prompt: "Al bar ordina 3 caffè da 1,10 € l'uno e 2 cappuccini da 1,50 € l'uno. Paga con 10 €. Quanto riceve di resto?", options: ["3,30 €", "3,70 €", "3,80 €", "4,70 €"], correctAnswer: "3,70 €", explanation: "I caffè costano 3 × 1,10 € = 3,30 € e i cappuccini 2 × 1,50 € = 3,00 €. La spesa è 6,30 €. Il resto è 10,00 € - 6,30 € = 3,70 €.")
        ]
    )

    private static let groceryBestValue = Exercise(
        title: "Al supermercato: quale conviene?",
