        trackedType: nil,
        difficulty: .easy,
        groupKey: "groceryBestValue",
        isHeldForReview: false,
        items: [
            ExerciseItem(id: UUID(), prompt: "Pasta. Quale offerta costa meno al chilo?\nOfferta A: 500 g a 0,95 €\nOfferta B: 1 kg a 1,70 €", options: ["Offerta A — 500 g a 0,95 €", "Offerta B — 1 kg a 1,70 €"], correctAnswer: "Offerta B — 1 kg a 1,70 €", explanation: "A costa 0,95 € × 2 = 1,90 € al chilo. B costa 1,70 € al chilo. B è più conveniente."),
            ExerciseItem(id: UUID(), prompt: "Latte. Quale offerta costa meno al litro?\nOfferta A: 1 l a 1,40 €\nOfferta B: confezione da 6 bottiglie da 1 l a 7,50 €", options: ["Offerta A — 1 l a 1,40 €", "Offerta B — 6 l a 7,50 €"], correctAnswer: "Offerta B — 6 l a 7,50 €", explanation: "A costa 1,40 € al litro. B costa 7,50 € : 6 = 1,25 € al litro. B è più conveniente."),
            ExerciseItem(id: UUID(), prompt: "Olio d'oliva. Quale offerta costa meno al litro?\nOfferta A: 500 ml a 3,50 €\nOfferta B: 1 l a 7,40 €", options: ["Offerta A — 500 ml a 3,50 €", "Offerta B — 1 l a 7,40 €"], correctAnswer: "Offerta A — 500 ml a 3,50 €", explanation: "A costa 3,50 € × 2 = 7,00 € al litro. B costa 7,40 € al litro. A è più conveniente."),
            ExerciseItem(id: UUID(), prompt: "Riso. Quale offerta costa meno al chilo?\nOfferta A: 1 kg a 2,40 €\nOfferta B: 2 kg a 4,60 €", options: ["Offerta A — 1 kg a 2,40 €", "Offerta B — 2 kg a 4,60 €"], correctAnswer: "Offerta B — 2 kg a 4,60 €", explanation: "A costa 2,40 € al chilo. B costa 4,60 € : 2 = 2,30 € al chilo. B è più conveniente."),
            ExerciseItem(id: UUID(), prompt: "Yogurt. Quale offerta costa meno al chilo?\nOfferta A: 4 vasetti da 125 g a 1,80 €\nOfferta B: 2 vasetti da 125 g a 1,00 €", options: ["Offerta A — 4 vasetti (500 g) a 1,80 €", "Offerta B — 2 vasetti (250 g) a 1,00 €"], correctAnswer: "Offerta A — 4 vasetti (500 g) a 1,80 €", explanation: "A: 500 g a 1,80 € significa 1,80 € × 2 = 3,60 € al chilo. B: 250 g a 1,00 € significa 1,00 € × 4 = 4,00 € al chilo. A è più conveniente."),
            ExerciseItem(id: UUID(), prompt: "Acqua minerale. Quale offerta costa meno al litro?\nOfferta A: 6 bottiglie da 1,5 l a 2,70 €\nOfferta B: 12 bottiglie da 0,5 l a 2,40 €", options: ["Offerta A — 6 × 1,5 l (9 l) a 2,70 €", "Offerta B — 12 × 0,5 l (6 l) a 2,40 €"], correctAnswer: "Offerta A — 6 × 1,5 l (9 l) a 2,70 €", explanation: "A: 9 litri a 2,70 € significa 2,70 € : 9 = 0,30 € al litro. B: 6 litri a 2,40 € significa 2,40 € : 6 = 0,40 € al litro. A è più conveniente."),
            ExerciseItem(id: UUID(), prompt: "Caffè macinato. Quale offerta costa meno al chilo?\nOfferta A: 250 g a 3,50 €\nOfferta B: 500 g a 6,50 €", options: ["Offerta A — 250 g a 3,50 €", "Offerta B — 500 g a 6,50 €"], correctAnswer: "Offerta B — 500 g a 6,50 €", explanation: "A costa 3,50 € × 4 = 14,00 € al chilo. B costa 6,50 € × 2 = 13,00 € al chilo. B è più conveniente."),
            ExerciseItem(id: UUID(), prompt: "Biscotti. Quale offerta costa meno al chilo?\nOfferta A: 400 g a 2,00 €\nOfferta B: 750 g a 3,90 €", options: ["Offerta A — 400 g a 2,00 €", "Offerta B — 750 g a 3,90 €"], correctAnswer: "Offerta A — 400 g a 2,00 €", explanation: "A: 2,00 € : 0,4 = 5,00 € al chilo. B: 3,90 € : 0,75 = 5,20 € al chilo. A è più conveniente."),
            ExerciseItem(id: UUID(), prompt: "Detersivo liquido. Quale offerta costa meno al litro?\nOfferta A: 2 l a 5,00 €\nOfferta B: 3 l a 6,90 €", options: ["Offerta A — 2 l a 5,00 €", "Offerta B — 3 l a 6,90 €"], correctAnswer: "Offerta B — 3 l a 6,90 €", explanation: "A costa 5,00 € : 2 = 2,50 € al litro. B costa 6,90 € : 3 = 2,30 € al litro. B è più conveniente."),
            ExerciseItem(id: UUID(), prompt: "Pelati in lattina. Quale offerta costa meno al chilo?\nOfferta A: 3 lattine da 400 g a 2,40 €\nOfferta B: 2 lattine da 400 g a 1,84 €", options: ["Offerta A — 3 lattine (1,2 kg) a 2,40 €", "Offerta B — 2 lattine (800 g) a 1,84 €"], correctAnswer: "Offerta A — 3 lattine (1,2 kg) a 2,40 €", explanation: "A: 2,40 € : 1,2 = 2,00 € al chilo. B: 1,84 € : 0,8 = 2,30 € al chilo. A è più conveniente."),
            ExerciseItem(id: UUID(), prompt: "Mele. Quale offerta costa meno al chilo?\nOfferta A: sacchetto da 2 kg a 3,20 €\nOfferta B: mele sfuse, 1,5 kg a 2,25 €", options: ["Offerta A — 2 kg a 3,20 €", "Offerta B — 1,5 kg a 2,25 €"], correctAnswer: "Offerta B — 1,5 kg a 2,25 €", explanation: "A costa 3,20 € : 2 = 1,60 € al chilo. B costa 2,25 € : 1,5 = 1,50 € al chilo. B è più conveniente."),
            ExerciseItem(id: UUID(), prompt: "Grana grattugiato. Quale offerta costa meno al chilo?\nOfferta A: 200 g a 3,40 €\nOfferta B: 300 g a 4,50 €", options: ["Offerta A — 200 g a 3,40 €", "Offerta B — 300 g a 4,50 €"], correctAnswer: "Offerta B — 300 g a 4,50 €", explanation: "A costa 3,40 € × 5 = 17,00 € al chilo. B costa 4,50 € : 0,3 = 15,00 € al chilo. B è più conveniente."),
            ExerciseItem(id: UUID(), prompt: "Zucchero. Quale offerta costa meno al chilo?\nOfferta A: 2 kg a 2,10 €\nOfferta B: 1 kg a 1,15 €", options: ["Offerta A — 2 kg a 2,10 €", "Offerta B — 1 kg a 1,15 €"], correctAnswer: "Offerta A — 2 kg a 2,10 €", explanation: "A costa 2,10 € : 2 = 1,05 € al chilo. B costa 1,15 € al chilo. A è più conveniente."),
            ExerciseItem(id: UUID(), prompt: "Tonno in scatola. Quale offerta costa meno al chilo?\nOfferta A: 3 scatolette da 80 g a 3,60 €\nOfferta B: 4 scatolette da 80 g a 4,48 €", options: ["Offerta A — 3 scatolette (240 g) a 3,60 €", "Offerta B — 4 scatolette (320 g) a 4,48 €"], correctAnswer: "Offerta B — 4 scatolette (320 g) a 4,48 €", explanation: "A: 3,60 € : 0,24 = 15,00 € al chilo. B: 4,48 € : 0,32 = 14,00 € al chilo. B è più conveniente."),
            ExerciseItem(id: UUID(), prompt: "Carta igienica. Quale offerta costa meno per rotolo?\nOfferta A: 8 rotoli a 2,80 €\nOfferta B: 12 rotoli a 3,60 €", options: ["Offerta A — 8 rotoli a 2,80 €", "Offerta B — 12 rotoli a 3,60 €"], correctAnswer: "Offerta B — 12 rotoli a 3,60 €", explanation: "A costa 2,80 € : 8 = 0,35 € a rotolo. B costa 3,60 € : 12 = 0,30 € a rotolo. B è più conveniente.")
        ]
    )

    private static let functionalWriting = Exercise(
        title: "Scrivere nella vita quotidiana",
        instructions: "Legga la situazione e scriva il testo richiesto.",
        section: .functionalSkills,
        type: .openEnded,
        trackedType: nil,
        difficulty: .medium,
        groupKey: "functionalWriting",
        isHeldForReview: false,
        items: [
            ExerciseItem(id: UUID(), prompt: "Domani non sarà in casa e aspetta un pacco. Scriva un biglietto breve per il vicino, chiedendogli di ritirarlo.", options: [], correctAnswer: "Gentile signora Bianchi,\ndomani non sarò in casa dalle ore 09:00 alle ore 18:00. Aspetto un pacco: potrebbe ritirarlo per me? Passerò a prenderlo in serata.\nGrazie mille.\nMario Rossi, interno 5", explanation: "Il biglietto dice chi scrive, che cosa serve, quando e un ringraziamento. Il tono è gentile e ci sono le ore in formato a 24 ore."),
            ExerciseItem(id: UUID(), prompt: "Deve spostare una visita dal dentista fissata il 14/10 alle ore 15:30. Scriva un breve messaggio allo studio.", options: [], correctAnswer: "Buongiorno, sono Mario Rossi. Il 14/10 alle ore 15:30 ho un appuntamento, ma non posso venire. Potrei spostarlo a un altro giorno, di mattina? La ringrazio e attendo una risposta. Cordiali saluti.", explanation: "Il messaggio indica nome, data e ora dell'appuntamento, il motivo della richiesta e una proposta. La data è nel formato giorno/mese."),
            ExerciseItem(id: UUID(), prompt: "Compili la riga di un modulo postale con il Suo nome e il Suo indirizzo. Si chiama Anna Verdi e abita in via Garibaldi, numero 8, a Milano, CAP 20121.", options: [], correctAnswer: "Anna Verdi, Via Garibaldi 8, 20121 Milano (MI)", explanation: "In Italia l'indirizzo si scrive così: via e numero, poi CAP di 5 cifre, città e sigla della provincia tra parentesi."),
            ExerciseItem(id: UUID(), prompt: "Scriva una lista della spesa con cinque cose da comprare, ciascuna con la quantità.", options: [], correctAnswer: "- pane: 500 g\n- latte: 2 l\n- mele: 1 kg\n- uova: 6\n- formaggio: 200 g", explanation: "Una lista chiara dice che cosa e quanto comprare, con le unità metriche. Una riga per prodotto si legge subito anche al supermercato."),
            ExerciseItem(id: UUID(), prompt: "Sua figlia Laura ha chiesto a che ora arriverà da lei domani. Scriva un messaggio breve: arriva alle 17:30 e porta una torta.", options: [], correctAnswer: "Cara Laura, domani arrivo alle ore 17:30. Porto io la torta. A domani, un abbraccio. Mamma", explanation: "Il messaggio risponde alla domanda subito, ha l'ora in formato a 24 ore e un saluto affettuoso: tra familiari si usa un tono informale."),
            ExerciseItem(id: UUID(), prompt: "Il Suo vicino, il signor Paolo, andrà in farmacia al posto Suo. Scriva il biglietto che gli lascia, con la ricetta e la tessera sanitaria.", options: [], correctAnswer: "Gentile signor Paolo, Le lascio la ricetta e la tessera sanitaria. In farmacia chieda il medicinale scritto sulla ricetta. Le darò i soldi appena torna. La ringrazio.", explanation: "Il biglietto dice che cosa si lascia, che cosa fare e come sdebitarsi. Si usa il «Lei», adatto a un vicino, e un tono cortese. Ricetta e tessera sanitaria sono i due documenti necessari."),
            ExerciseItem(id: UUID(), prompt: "Scriva il testo di una cartolina di auguri di Natale per una vecchia amica.", options: [], correctAnswer: "Cara Giulia, ti auguro un Natale sereno insieme alle persone che ami. Spero di rivederti presto. Con affetto, Anna", explanation: "Una cartolina è breve: ha un saluto, un augurio e una chiusura calorosa. Tra amiche si usa il «tu»."),
            ExerciseItem(id: UUID(), prompt: "La lampadina della scala del condominio è bruciata da due giorni. Scriva un messaggio all'amministratore.", options: [], correctAnswer: "Gentile amministratore, Le segnalo che la lampadina del secondo piano della scala B è bruciata da due giorni. La scala è buia e potrebbe essere pericoloso. Può farla sostituire? Grazie. Mario Rossi, Via Dante 15, 50122 Firenze (FI)", explanation: "Il messaggio indica il problema, dove si trova e perché è importante. La richiesta è chiara e il tono formale."),
            ExerciseItem(id: UUID(), prompt: "Sul modulo del medico c'è la riga: «Numero di telefono e orario in cui possiamo richiamarLa». Il Suo cellulare è 333 123 4567 e può rispondere dalle 09:00 alle 12:00. Che cosa scrive?", options: [], correctAnswer: "333 123 4567, dalle ore 09:00 alle ore 12:00", explanation: "Un numero di cellulare si scrive a gruppi (3 + 3 + 4 cifre). L'orario in 24 ore non lascia dubbi."),
            ExerciseItem(id: UUID(), prompt: "Vuole prenotare dalla panetteria 2 kg di pane per sabato, da ritirare alle 10:00. Scriva il messaggio.", options: [], correctAnswer: "Buongiorno, vorrei prenotare 2 kg di pane per sabato, da ritirare alle ore 10:00. Il mio nome è Rossi. Il mio numero è 333 123 4567. Grazie.", explanation: "Un ordine chiaro indica la quantità, il giorno e l'ora del ritiro, più il nome e un recapito per eventuali problemi.")
        ]
    )

    private static let cookingSteps = Exercise(
        title: "In cucina: i passaggi giusti",
        instructions: "Metta i passaggi nell'ordine corretto.",
        section: .functionalSkills,
        type: .sequencing,
        trackedType: .sequencing,
        difficulty: .medium,
        groupKey: "cookingSteps",
        isHeldForReview: false,
        items: [
            ExerciseItem(id: UUID(), prompt: "Come si prepara un piatto di spaghetti al pomodoro?", options: ["Scolare la pasta", "Mettere l'acqua nella pentola", "Condire con il sugo", "Calare gli spaghetti nell'acqua che bolle", "Salare l'acqua e portarla a bollore"], correctAnswer: "Mettere l'acqua nella pentola | Salare l'acqua e portarla a bollore | Calare gli spaghetti nell'acqua che bolle | Scolare la pasta | Condire con il sugo", explanation: "La pasta va cotta in acqua già bollente. Solo quando è cotta si scola e si condisce."),
            ExerciseItem(id: UUID(), prompt: "Come si cuociono le patate lesse?", options: ["Scolare le patate", "Portare l'acqua a bollore", "Controllare la cottura con una forchetta", "Lavare le patate", "Mettere le patate in pentola con acqua fredda"], correctAnswer: "Lavare le patate | Mettere le patate in pentola con acqua fredda | Portare l'acqua a bollore | Controllare la cottura con una forchetta | Scolare le patate", explanation: "Le patate si lavano prima di cuocerle e partono dall'acqua fredda. La forchetta serve a verificare che siano tenere prima di scolarle."),
            ExerciseItem(id: UUID(), prompt: "Come si cuociono le uova sode?", options: ["Sgusciare le uova", "Accendere il fuoco", "Raffreddare le uova sotto l'acqua fredda", "Mettere le uova in un pentolino con acqua fredda", "Cuocere per dieci minuti dal bollore"], correctAnswer: "Mettere le uova in un pentolino con acqua fredda | Accendere il fuoco | Cuocere per dieci minuti dal bollore | Raffreddare le uova sotto l'acqua fredda | Sgusciare le uova", explanation: "Le uova partono dall'acqua fredda per non rompersi. Il guscio si toglie quando sono raffreddate e non scottano."),
            ExerciseItem(id: UUID(), prompt: "Come si prepara un'insalata di pomodori e lattuga?", options: ["Tagliare la lattuga asciutta e i pomodori", "Lavare la lattuga", "Condire con olio e sale", "Mescolare e servire", "Asciugare la lattuga"], correctAnswer: "Lavare la lattuga | Asciugare la lattuga | Tagliare la lattuga asciutta e i pomodori | Condire con olio e sale | Mescolare e servire", explanation: "La verdura si lava e si asciuga prima di tagliare e condire. Il condimento va aggiunto alla fine, altrimenti l'insalata si ammorbidisce."),
            ExerciseItem(id: UUID(), prompt: "Come si prepara una fetta di pane tostato con la marmellata?", options: ["Aspettare che il pane sia dorato", "Togliere il pane con attenzione perché è caldo", "Spalmare la marmellata", "Mettere il pane nel tostapane e abbassare la leva"], correctAnswer: "Mettere il pane nel tostapane e abbassare la leva | Aspettare che il pane sia dorato | Togliere il pane con attenzione perché è caldo | Spalmare la marmellata", explanation: "La marmellata si mette quando il pane è pronto. Toglierlo con attenzione evita di scottarsi."),
            ExerciseItem(id: UUID(), prompt: "Come si prepara una minestra di verdure?", options: ["Servire la minestra calda", "Cuocere a fuoco basso", "Mettere le verdure in pentola con l'acqua", "Salare a fine cottura", "Lavare e tagliare le verdure"], correctAnswer: "Lavare e tagliare le verdure | Mettere le verdure in pentola con l'acqua | Cuocere a fuoco basso | Salare a fine cottura | Servire la minestra calda", explanation: "Le verdure vanno prima pulite e tagliate. Cuociono piano, poi si aggiusta di sale e si serve."),
            ExerciseItem(id: UUID(), prompt: "Come si prepara una frittata?", options: ["Versare le uova nella padella calda", "Rompere le uova in una ciotola", "Girare la frittata e finire la cottura", "Sbattere le uova con un pizzico di sale"], correctAnswer: "Rompere le uova in una ciotola | Sbattere le uova con un pizzico di sale | Versare le uova nella padella calda | Girare la frittata e finire la cottura", explanation: "Le uova vanno prima rotte e sbattute; solo dopo si versano nella padella calda e, a metà cottura, si gira la frittata."),
            ExerciseItem(id: UUID(), prompt: "Come si prepara una tisana?", options: ["Togliere la bustina dalla tazza", "Versare l'acqua calda nella tazza con la bustina già dentro", "Attendere tre minuti", "Scaldare l'acqua nel bollitore"], correctAnswer: "Scaldare l'acqua nel bollitore | Versare l'acqua calda nella tazza con la bustina già dentro | Attendere tre minuti | Togliere la bustina dalla tazza", explanation: "L'acqua si scalda prima; versata sulla bustina, la tisana si infonde per qualche minuto e solo alla fine si toglie la bustina."),
            ExerciseItem(id: UUID(), prompt: "Come si cuoce una pizza surgelata nel forno?", options: ["Infornare per il tempo scritto sulla confezione", "Accendere il forno", "Spegnere il forno e sfornare con i guanti", "Quando il forno è caldo, mettere sulla teglia la pizza senza involucro"], correctAnswer: "Accendere il forno | Quando il forno è caldo, mettere sulla teglia la pizza senza involucro | Infornare per il tempo scritto sulla confezione | Spegnere il forno e sfornare con i guanti", explanation: "Il forno deve essere caldo prima di infornare; la pizza si cuoce per il tempo indicato e solo alla fine si spegne il forno per sfornare con i guanti."),
            ExerciseItem(id: UUID(), prompt: "Come si scalda un po' di latte?", options: ["Aggiungere lo zucchero nella tazza piena", "Togliere il pentolino dal fuoco prima che il latte bolla", "Versare il latte nel pentolino", "Versare il latte nella tazza", "Scaldare a fuoco basso mescolando"], correctAnswer: "Versare il latte nel pentolino | Scaldare a fuoco basso mescolando | Togliere il pentolino dal fuoco prima che il latte bolla | Versare il latte nella tazza | Aggiungere lo zucchero nella tazza piena", explanation: "Il latte sale e trabocca quando bolle, quindi si toglie dal fuoco prima. Lo zucchero si aggiunge solo dopo, nella tazza piena.")
        ]
    )

    private static let dailyLifeSkills = Exercise(
        title: "Cose da fare ogni giorno",
        instructions: "Legga la domanda e scriva come si fa.",
        section: .functionalSkills,
        type: .openEnded,
        trackedType: nil,
        difficulty: .medium,
        groupKey: "dailyLifeSkills",
        isHeldForReview: false,
        items: [
            ExerciseItem(id: UUID(), prompt: "Come si spedisce una lettera raccomandata all'ufficio postale?", options: [], correctAnswer: "Prendo il numero all'ingresso, aspetto il mio turno e allo sportello consegno la lettera. Compilo il modulo con il nome e l'indirizzo del destinatario e pago. Conservo la ricevuta.", explanation: "La ricevuta è la prova della spedizione. Con essa si può controllare dove si trova la lettera."),
            ExerciseItem(id: UUID(), prompt: "Come si paga in un negozio con la carta?", options: [], correctAnswer: "Avvicino o inserisco la carta nel lettore, controllo l'importo sul display e, se richiesto, digito il PIN coprendo la tastiera con la mano. Poi prendo lo scontrino.", explanation: "Coprire la tastiera impedisce a chi sta dietro di vedere il PIN. Controllare l'importo evita errori."),
            ExerciseItem(id: UUID(), prompt: "Come si preleva del denaro allo sportello bancomat?", options: [], correctAnswer: "Inserisco la carta, digito il PIN, scelgo «prelievo» e l'importo. Aspetto la carta, poi i soldi e lo scontrino, e li prendo prima di andare via.", explanation: "Si controlla di riprendere carta e contanti prima di allontanarsi. Non si accetta aiuto da sconosciuti."),
            ExerciseItem(id: UUID(), prompt: "Come si usa il biglietto dell'autobus appena salito?", options: [], correctAnswer: "Appena salito, lo convalido nell'apparecchio che c'è a bordo e controllo che sia timbrato. Lo tengo con me fino alla fine del viaggio, perché può essere controllato.", explanation: "Un biglietto non convalidato non vale e si rischia una multa. Per questo lo si timbra subito."),
            ExerciseItem(id: UUID(), prompt: "Come si prenota una visita dal medico per telefono?", options: [], correctAnswer: "Telefono allo studio e dico il nome e il motivo della visita. Chiedo un giorno e un'ora, li scrivo su un foglio e ripeto per essere sicuro. Il giorno della visita porto la tessera sanitaria.", explanation: "Scrivere data e ora e ripeterle evita equivoci. La tessera sanitaria serve per identificarsi."),
            ExerciseItem(id: UUID(), prompt: "Come si compra un biglietto del treno alla biglietteria automatica?", options: [], correctAnswer: "Scelgo la lingua, indico la stazione di partenza e di arrivo, il giorno e l'ora. Controllo il prezzo, pago con carta o contanti e prendo il biglietto e il resto.", explanation: "Si ricontrolla sempre la destinazione prima di pagare, perché il biglietto sbagliato non si cambia facilmente."),
            ExerciseItem(id: UUID(), prompt: "Come si chiede la strada a un passante?", options: [], correctAnswer: "Saluto con gentilezza e dico: «Scusi, sa dirmi come arrivare alla stazione?». Ascolto con attenzione, ripeto le indicazioni per verificare e ringrazio.", explanation: "Ripetere la risposta aiuta a ricordarla e a capire se le indicazioni sono state comprese bene."),
            ExerciseItem(id: UUID(), prompt: "Come si ritira un medicinale in farmacia quando serve la ricetta?", options: [], correctAnswer: "Vado in farmacia con la ricetta del medico e con la tessera sanitaria, le consegno al farmacista e chiedo di spiegarmi come usare il medicinale. Poi pago e prendo lo scontrino.", explanation: "Senza ricetta alcuni medicinali non si possono avere. Il farmacista può spiegare le informazioni importanti."),
            ExerciseItem(id: UUID(), prompt: "Che cosa si controlla sullo scontrino dopo aver fatto la spesa?", options: [], correctAnswer: "Controllo che i prodotti scritti siano quelli che ho comprato, che i prezzi siano giusti e che lo sconto sia stato applicato. Se trovo un errore, torno subito alla cassa.", explanation: "Gli errori si correggono più facilmente subito, mentre si è ancora al negozio."),
            ExerciseItem(id: UUID(), prompt: "Come si controlla l'orario di un treno in stazione?", options: [], correctAnswer: "Guardo il tabellone delle partenze, cerco la mia destinazione e l'ora, e leggo il numero del binario. Poi vado al binario in anticipo.", explanation: "Il binario può cambiare. Per questo conviene controllare il tabellone anche poco prima della partenza."),
            ExerciseItem(id: UUID(), prompt: "Come si fa a chiamare un taxi?", options: [], correctAnswer: "Telefono alla radio taxi della mia città, dico il nome, l'indirizzo dove mi trovo e dove voglio andare. Aspetto fuori, in un posto ben visibile, e controllo che sia un taxi autorizzato.", explanation: "Un taxi autorizzato ha la scritta e il numero sulla porta e il tassametro acceso."),
            ExerciseItem(id: UUID(), prompt: "Come si cambia un appuntamento dal parrucchiere per telefono?", options: [], correctAnswer: "Telefono, dico il mio nome e il giorno e l'ora dell'appuntamento. Spiego che devo spostarlo e chiedo un altro giorno. Ripeto la nuova data e la scrivo.", explanation: "Avvisare per tempo è corretto verso chi lavora. Scrivere la nuova data evita di dimenticarla."),
            ExerciseItem(id: UUID(), prompt: "Come si può organizzare la settimana per non dimenticare gli impegni?", options: [], correctAnswer: "Uso un'agenda o un calendario appeso in cucina e ci scrivo ogni impegno con il giorno e l'ora. Lo guardo ogni mattina e lo ricontrollo la sera, prima di andare a letto.", explanation: "Un posto fisso per gli impegni e un controllo regolare aiutano la memoria."),
            ExerciseItem(id: UUID(), prompt: "Come si fa la raccolta differenziata dei rifiuti in casa?", options: [], correctAnswer: "Separo i rifiuti in contenitori diversi: carta, plastica, vetro e rifiuti organici (umido). Metto fuori ogni contenitore nel giorno indicato dal calendario del Comune.", explanation: "Separare bene permette il riciclo. Il calendario del Comune dice quando passano a ritirare ciascun tipo di rifiuto."),
            ExerciseItem(id: UUID(), prompt: "Come si paga una bolletta con il bollettino all'ufficio postale?", options: [], correctAnswer: "Porto il bollettino, prendo il numero e aspetto il turno. Allo sportello consegno il bollettino e pago l'importo indicato. Conservo la ricevuta timbrata come prova.", explanation: "La ricevuta dimostra che si è pagato. Conviene tenerla per qualche tempo."),
            ExerciseItem(id: UUID(), prompt: "Come si fa la spesa in modo ordinato, senza dimenticare nulla?", options: [], correctAnswer: "Prima scrivo la lista a casa e la divido per reparti: frutta e verdura, latticini, panetteria, bevande. In negozio seguo i reparti e spunto ogni cosa che metto nel carrello.", explanation: "Una lista per reparti riduce i giri e le dimenticanze. Spuntare aiuta a controllare."),
            ExerciseItem(id: UUID(), prompt: "Come si chiede un certificato al Comune?", options: [], correctAnswer: "Vado all'ufficio anagrafe con un documento d'identità. Dico quale certificato mi serve e a che cosa, compilo il modulo e pago eventuali spese. Chiedo quando posso ritirarlo.", explanation: "Il documento serve a identificarsi. Chiedere la data di ritiro permette di organizzarsi."),
            ExerciseItem(id: UUID(), prompt: "Come ci si ricorda di prendere le chiavi quando si esce di casa?", options: [], correctAnswer: "Metto le chiavi sempre nello stesso posto, vicino alla porta. Prima di chiudere controllo con la mano di averle in tasca o nella borsa.", explanation: "Un'abitudine fissa serve più della memoria. Il gesto di controllare fa da promemoria."),
            ExerciseItem(id: UUID(), prompt: "Come si salva un nuovo numero nella rubrica del cellulare?", options: [], correctAnswer: "Apro la rubrica e premo il segno «+» per aggiungere un contatto. Scrivo il nome e il numero, controllo che le cifre siano giuste e premo «Salva».", explanation: "Controllare le cifre evita di chiamare un numero sbagliato. Un nome chiaro rende il contatto facile da trovare."),
            ExerciseItem(id: UUID(), prompt: "Come si legge la data di scadenza su una confezione di latticini?", options: [], correctAnswer: "Cerco la scritta «da consumarsi entro» o «scadenza» e leggo il giorno e il mese. Se la data è passata, non compro e non mangio il prodotto.", explanation: "Controllare la scadenza al momento dell'acquisto e prima di mangiare evita di buttare cibo e di rischiare disturbi.")
        ]
    )
}
